contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take a dummy uint parameter so the checker ranges over inputs.
    // The test calls refund and then checks the observable effects:
    // - refund must not increase address(c).balance
    // - withdraw(0) must succeed (i.e., not revert) if refund succeeded
    function run(uint256 dummy) public payable {
        require(true);

        uint256 beforeContract = address(c).balance;

        bool refundedReverted;
        c.refund(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            refundedReverted = true;
        } else {
            refundedReverted = false;
        }

        uint256 afterContract = address(c).balance;

        bool withdraw0Reverted;
        c.withdraw(0); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            withdraw0Reverted = true;
        } else {
            withdraw0Reverted = false;
        }

        // If refund succeeded, then contract balance did not increase and withdraw(0) must succeed.
        assert(refundedReverted || (afterContract <= beforeContract && withdraw0Reverted == false));
    }

    receive() external payable {}
}

