// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 dummy) internal {
        vm.assume(true);
        uint256 beforeContract = address(c).balance;
        bool refundedReverted;
        try c.refund() {
            refundedReverted = false;
        } catch {
            refundedReverted = true;
        }
        uint256 afterContract = address(c).balance;
        bool withdraw0Reverted;
        try c.withdraw(0) {
            withdraw0Reverted = false;
        } catch {
            withdraw0Reverted = true;
        }
        assertTrue(refundedReverted || (afterContract <= beforeContract && withdraw0Reverted == false));
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
